// AllActions returns every catalog IAM action string (sorted, deduplicated).
func AllActions() []string {
	return allActions
}

// KnownAction reports whether action is recognized in the current catalog.
func KnownAction(action string) bool {
	if action == "" {
		return false
	}
	_, ok := knownActions[action]
	return ok
}
